-- ROLLBACK of 31-35: deletes the new draft set versions of the target sets (no attempts can reference a draft) and archives imported quant problems no live set uses. Published sets untouched.
-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_QUANT=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

do $rbq$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.name = any (array['SAT Practice Test 6','SAT Practice Test 10','SAT Practice Test 11','SAT Practice Test 12','SAT Practice Test 13','SAT Practice Test 16','SAT Practice Test 17','SAT Practice Test 18','SAT Practice Test 19','SAT Practice Test 20','SAT Practice Test 22','SAT Practice Test 23','SAT Practice Test 24','SAT Practice Test 25','SAT Practice Test 27','SAT Practice Test 30']) and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no);
  get diagnostics v_n = row_count; raise notice 'draft set versions removed: %', v_n;
  delete from problem_keywords where problem_id in (select pv.problem_id from problem_versions pv where pv.quality->'mockExamGeneration'->>'gid' = any (array['quant-pair-compare-20261027','quant-ratio-vs-baseline-20261090','quant-target-met-20261097','quant-max-change-20261104','quant-max-step-20261111','quant-pair-compare-20261118','quant-ratio-vs-baseline-20261293','quant-target-met-20261300','quant-max-change-20261307','quant-max-step-20261314','quant-pair-compare-20261321','quant-ratio-vs-baseline-20261356','quant-target-met-20261363','quant-max-change-20261370','quant-max-step-20261377','quant-pair-compare-20261384','quant-ratio-vs-baseline-20261447','quant-target-met-20261454','quant-max-change-20261461','quant-max-step-20261468','quant-pair-compare-20261475','quant-ratio-vs-baseline-20261622','quant-target-met-20261636','quant-max-change-20261678','quant-max-step-20261685','quant-pair-compare-20261692','quant-ratio-vs-baseline-20261727','quant-target-met-20261741','quant-max-change-20261755','quant-max-step-20261762','quant-pair-compare-20261769','quant-ratio-vs-baseline-20261874','quant-target-met-20261888','quant-max-change-20261923','quant-max-step-20261930','quant-pair-compare-20261937']));
  update problems p set archived_at = now() where p.archived_at is null and p.id in (select pv.problem_id from problem_versions pv where pv.quality->'mockExamGeneration'->>'gid' = any (array['quant-pair-compare-20261027','quant-ratio-vs-baseline-20261090','quant-target-met-20261097','quant-max-change-20261104','quant-max-step-20261111','quant-pair-compare-20261118','quant-ratio-vs-baseline-20261293','quant-target-met-20261300','quant-max-change-20261307','quant-max-step-20261314','quant-pair-compare-20261321','quant-ratio-vs-baseline-20261356','quant-target-met-20261363','quant-max-change-20261370','quant-max-step-20261377','quant-pair-compare-20261384','quant-ratio-vs-baseline-20261447','quant-target-met-20261454','quant-max-change-20261461','quant-max-step-20261468','quant-pair-compare-20261475','quant-ratio-vs-baseline-20261622','quant-target-met-20261636','quant-max-change-20261678','quant-max-step-20261685','quant-pair-compare-20261692','quant-ratio-vs-baseline-20261727','quant-target-met-20261741','quant-max-change-20261755','quant-max-step-20261762','quant-pair-compare-20261769','quant-ratio-vs-baseline-20261874','quant-target-met-20261888','quant-max-change-20261923','quant-max-step-20261930','quant-pair-compare-20261937']))
    and not exists (select 1 from mock_exam_set_items i join mock_exam_sets o on o.id = i.exam_set_id and o.archived_at is null and o.status <> 'archived' where i.problem_id = p.id);
  get diagnostics v_n = row_count; raise notice 'quant problems archived: %', v_n;
end $rbq$;
